import machine
import time

def hardware_button_read(pin, debounce_ms, active_low):
  button = machine.Pin(pin, machine.Pin.IN, machine.Pin.PULL_UP if active_low else machine.Pin.PULL_DOWN)
  value = button.value()
  if active_low:
    pressed = value == 0
  else:
    pressed = value == 1
  if not pressed:
    return False
  if debounce_ms < 0:
    debounce_ms = 0
  if debounce_ms > 1000:
    debounce_ms = 1000
  if debounce_ms > 0:
    time.sleep_ms(int(debounce_ms))
  value = button.value()
  if active_low:
    return value == 0
  return value == 1


while True:
  if hardware_button_read(4, 20, True):
    machine.Pin(2, machine.Pin.OUT).value(1)
  if not hardware_button_read(4, 20, True):
    machine.Pin(2, machine.Pin.OUT).value(0)
  time.sleep_ms(20)

import machine
import time

_pwm_channels = {}

def hardware_set_pwm(pin, freq, duty):
  pwm = _pwm_channels.get(pin)
  if pwm is None:
    pwm = machine.PWM(machine.Pin(pin), freq=freq, duty=duty)
    _pwm_channels[pin] = pwm
  else:
    pwm.freq(freq)
    pwm.duty(duty)


while True:
  hardware_set_pwm(2, 1000, (time.ticks_ms() // 2) % 1024)
  time.sleep_ms(2)

